# One site, served straight from disk.
server {
    listen 80;
    server_name shop.example.com;

    root /var/www/shop;
    index index.html;

    # Exact match: answered by nginx itself, useful for load-balancer health checks.
    location = /healthz {
        return 200 "ok\n";
    }

    # Static assets: regex location. Cached by browsers for a week.
    location ~* \.(css|js|png|jpg|svg)$ {
        expires 7d;
        add_header Cache-Control "public";
    }

    # Everything else: the file, then the directory, then 404.
    location / {
        try_files $uri $uri/ =404;
    }
}

