# Two copies of the API behind one name.
upstream checkout_api {
    server 127.0.0.1:8000 weight=2;   # gets two of every three requests
    server 127.0.0.1:8001;
    keepalive 16;                     # reuse connections to the backends
}

server {
    listen 80;
    server_name api.shop.example.com;

    location / {
        proxy_pass http://checkout_api;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_connect_timeout 3s;
        proxy_read_timeout 30s;
        # If one backend refuses or times out, retry the request on the next.
        proxy_next_upstream error timeout;
    }
}

// Declarative pipeline for checkout-api.
// Needs: Docker Pipeline plugin, a 'registry-creds' username/password credential,
// and kubectl configured on the agent.
pipeline {
  agent any

  options {
    timeout(time: 30, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  environment {
    REGISTRY = 'registry.example.com'
    IMAGE    = 'registry.example.com/shop/checkout-api'
  }

  stages {
    stage('Test') {
      agent { docker { image 'python:3.12-slim' } }
      steps {
        sh 'pip install -r requirements.txt -r requirements-dev.txt'
        sh 'pytest -q --junitxml=reports/junit.xml'
      }
      post {
        always { junit 'reports/junit.xml' }
      }
    }

    stage('Build image') {
      steps {
        // The commit SHA is the tag: every image maps to exactly one commit.
        sh 'docker build -t $IMAGE:$GIT_COMMIT .'
      }
    }

    stage('Scan image') {
      steps {
        sh 'trivy image --exit-code 1 --severity HIGH,CRITICAL $IMAGE:$GIT_COMMIT'
      }
    }

    stage('Push image') {
      steps {
        withCredentials([usernamePassword(credentialsId: 'registry-creds',
                                          usernameVariable: 'REG_USER',
                                          passwordVariable: 'REG_PASS')]) {
          sh 'echo "$REG_PASS" | docker login "$REGISTRY" -u "$REG_USER" --password-stdin'
          sh 'docker push $IMAGE:$GIT_COMMIT'
        }
      }
    }

    stage('Deploy to staging') {
      steps {
        sh 'kubectl -n staging set image deployment/checkout-api checkout-api=$IMAGE:$GIT_COMMIT'
        sh 'kubectl -n staging rollout status deployment/checkout-api --timeout=120s'
      }
    }

    stage('Approve production') {
      when { branch 'main' }
      steps {
        input message: 'Deploy this build to production?'
      }
    }

    stage('Deploy to production') {
      when { branch 'main' }
      steps {
        sh 'kubectl -n production set image deployment/checkout-api checkout-api=$IMAGE:$GIT_COMMIT'
        sh 'kubectl -n production rollout status deployment/checkout-api --timeout=180s'
      }
      post {
        failure {
          // A rollout that never becomes healthy is reverted automatically.
          sh 'kubectl -n production rollout undo deployment/checkout-api'
        }
      }
    }
  }
}

