// In the shared library repository: vars/standardPipeline.groovy
// One definition of "how we build a service", used by every repository.
def call(Map cfg = [:]) {
  pipeline {
    agent { label cfg.agent ?: 'linux' }
    options { timeout(time: 30, unit: 'MINUTES') }
    stages {
      stage('Checks') {
        steps { sh cfg.checkCommand ?: 'make check' }
      }
      stage('Build image') {
        steps { sh "docker build -t ${cfg.image}:${env.GIT_COMMIT} ." }
      }
      stage('Scan') {
        steps { sh "trivy image --exit-code 1 --severity HIGH,CRITICAL ${cfg.image}:${env.GIT_COMMIT}" }
      }
      stage('Publish') {
        when { branch 'main' }
        steps { sh "docker push ${cfg.image}:${env.GIT_COMMIT}" }
      }
    }
    post {
      failure { echo "Build failed: ${env.BUILD_URL}" }
    }
  }
}

