import json, random
import redis

r = redis.Redis.from_url(REDIS_URL, socket_timeout=0.05)  # fail fast: 50 ms

def get_product(product_id: str) -> dict:
    key = f"product:{product_id}"
    try:
        cached = r.get(key)
        if cached is not None:
            return json.loads(cached)              # hit
    except redis.RedisError:
        pass                                       # cache down: fall through to the database

    product = db_fetch_product(product_id)         # miss: the slow, authoritative read

    try:
        ttl = 300 + random.randint(0, 60)          # spread expiries so they do not all land together
        r.set(key, json.dumps(product), ex=ttl)
    except redis.RedisError:
        pass                                       # never fail a request because caching failed
    return product

def update_price(product_id: str, price: int) -> None:
    db_update_price(product_id, price)             # 1. write the source of truth
    r.delete(f"product:{product_id}")              # 2. invalidate; the next read repopulates

