// load.js: a ramping load test for checkout, run with k6 (illustrative).
import http from 'k6/http';
import { check, sleep } from 'k6';

export const options = {
  stages: [
    { duration: '2m', target: 50 },    // warm up
    { duration: '5m', target: 200 },   // normal peak
    { duration: '5m', target: 400 },   // sale-day forecast
    { duration: '2m', target: 0 },
  ],
  thresholds: {
    http_req_failed: ['rate<0.01'],          // fewer than 1% errors
    http_req_duration: ['p(95)<300'],        // 95% under 300 ms
  },
};

export default function () {
  const res = http.post(`${__ENV.BASE_URL}/checkout`,
    JSON.stringify({ items: [{ price: 120, qty: 2 }] }),
    { headers: { 'Content-Type': 'application/json' } });
  check(res, { 'status is 200': (r) => r.status === 200 });
  sleep(1);
}

